/* Generated from CPython 3.14.8's difflib by the script at the end of this comment: SequenceMatcher (ratio,
 * quick_ratio, real_quick_ratio, get_opcodes, get_grouped_opcodes, find_longest_match) and unified_diff on
 * random, structured and real inputs. Records, one per entry:
 *   C <mode> <autojunk> <junk>  start of a sequence case (mode str | u64 | text; junk - | blank | mod3)
 *   a:<s> b:<s>  the elements  (text mode: the two strings), n <na> <nb> their counts
 *   R <ratio> <quick> <real>  the doubles as 16 hex digits of their bits
 *   O <k> then k lines o <tag> i1 i2 j1 j2   get_opcodes()    G <n> <groups>, g <k>, o ...  grouped opcodes
 *   L alo ahi blo bhi i j k   find_longest_match    E  end of case
 *   U <na> <nb> <nout>, f: t: F: T: l: (names, dates, lineterm), N <n>, a: b:, x: expected lines   unified_diff
 * Strings use octal escapes. Regenerate: python gen.py <repo root> difflib_corpus.h
 * The listing windows come from the VC8 listings under build/decl_budget (cl_trace/*.asm) of that run.
 *
import difflib, random, struct, subprocess, glob, os, sys

REPO = sys.argv[1]
OUT = sys.argv[2]
rnd = random.Random(20261101)
lines_out = []  # one C string literal per entry


def hexd(x):
    return "%016x" % struct.unpack("<Q", struct.pack("<d", x))[0]


def emit(s):
    lines_out.append(s)


def enc(s):
    return "".join(
        c if (32 <= ord(c) < 127 and c not in '"\\?') else "".join("\\%03o" % b for b in c.encode("utf-8"))
        for c in s
    )


TAGS = {"replace": "r", "delete": "d", "insert": "i", "equal": "e"}


def joined(items):
    """The elements of one entry: the first character after the prefix is the separator, a printable one that no
    element contains (the empty sequence is just the prefix)."""
    if not items:
        return ""
    for sep in "|~^`#@$%&;,:+":
        if not any(sep in x for x in items):
            return sep + sep.join(items)
    raise SystemExit("no separator")



def ops_str(ops):
    return ";".join("%s%d,%d,%d,%d" % (TAGS[t], i1, i2, j1, j2) for t, i1, i2, j1, j2 in ops)


def seqcase(mode, a, b, autojunk, isjunk=None, jname="", groups=(), finds=0):
    """mode: str | u64 | text. Emits the sequences and the CPython results."""
    sm = difflib.SequenceMatcher(isjunk, a, b, autojunk=autojunk)
    emit("C %s %d %s" % (mode, 1 if autojunk else 0, jname or "-"))
    if mode == "text":
        emit("a:" + enc(a))
        emit("b:" + enc(b))
        emit("n 0 0")
    else:
        emit("n %d %d" % (len(a), len(b)))
        emit("a:" + joined([enc(x) if mode == "str" else str(x) for x in a]))
        emit("b:" + joined([enc(x) if mode == "str" else str(x) for x in b]))
    emit("R %s %s %s" % (hexd(sm.ratio()), hexd(sm.quick_ratio()), hexd(sm.real_quick_ratio())))
    emit("O " + ops_str(sm.get_opcodes()))
    for n in groups:
        gs = list(difflib.SequenceMatcher(isjunk, a, b, autojunk=autojunk).get_grouped_opcodes(n))
        emit("G %d %d %s" % (n, len(gs), "|".join(ops_str(g) for g in gs)))
    for _ in range(finds):
        la, lb = len(a), len(b)
        alo = rnd.randint(0, la)
        ahi = rnd.randint(alo, la)
        blo = rnd.randint(0, lb)
        bhi = rnd.randint(blo, lb)
        m = sm.find_longest_match(alo, ahi, blo, bhi)
        emit("L %d %d %d %d %d %d %d" % (alo, ahi, blo, bhi, m.a, m.b, m.size))
    emit("E")


def udiff_case(a, b, fromfile="", tofile="", fromdate="", todate="", n=3, lineterm="\n"):
    out = list(difflib.unified_diff(a, b, fromfile, tofile, fromdate, todate, n, lineterm))
    emit("U %d %d %d" % (len(a), len(b), len(out)))
    emit("f:" + enc(fromfile))
    emit("t:" + enc(tofile))
    emit("F:" + enc(fromdate))
    emit("T:" + enc(todate))
    emit("l:" + enc(lineterm))
    emit("N %d" % n)
    emit("a:" + joined([enc(x) for x in a]))
    emit("b:" + joined([enc(x) for x in b]))
    emit("x:" + joined([enc(x) for x in out]))
    emit("E")


WORDS = ["mov", "eax", "ecx", "edx", "push", "pop", "call", "ret", "add", "sub", "jmp", "jz", "lea", "xor", "cmp",
         "test", "esi", "edi", "esp", "ebp", "fld", "fstp", "x", "y", "z", "0x10", "[eax+4]", "dword ptr", ";", "", "é", "ж"]


def edit(seq, pool, nedits):
    s = list(seq)
    for _ in range(nedits):
        k = rnd.random()
        if k < 0.3 and s:
            i = rnd.randrange(len(s))
            del s[i : i + rnd.randint(1, 3)]
        elif k < 0.6:
            i = rnd.randint(0, len(s))
            s[i:i] = [rnd.choice(pool) for _ in range(rnd.randint(1, 4))]
        elif k < 0.8 and s:
            i = rnd.randrange(len(s))
            s[i] = rnd.choice(pool)
        elif k < 0.9 and len(s) > 4:  # move a block
            i = rnd.randrange(len(s) - 2)
            blk = s[i : i + rnd.randint(1, 4)]
            del s[i : i + len(blk)]
            j = rnd.randint(0, len(s))
            s[j:j] = blk
        elif s:  # duplicate a block
            i = rnd.randrange(len(s))
            blk = s[i : i + rnd.randint(1, 3)]
            j = rnd.randint(0, len(s))
            s[j:j] = blk
    return s


# 1. small random token sequences
for _ in range(300):
    pool = rnd.sample(WORDS, rnd.randint(2, 7))
    a = [rnd.choice(pool) for _ in range(rnd.randint(0, 28))]
    b = [rnd.choice(pool) for _ in range(rnd.randint(0, 28))]
    seqcase("str", a, b, rnd.random() < 0.5, groups=(rnd.choice([0, 1, 3]),) if rnd.random() < 0.5 else (), finds=1)

# 2. strings of repeated characters (code points)
ALPHA = ["ab", "abc", "aab", "abcd", "aé", "aжb", "ab 😀", "a b\t"]
for _ in range(280):
    al = rnd.choice(ALPHA)
    a = "".join(rnd.choice(al) for _ in range(rnd.randint(0, 50)))
    if rnd.random() < 0.5:
        b = "".join(edit(list(a), list(al), rnd.randint(0, 6)))
    else:
        b = "".join(rnd.choice(al) for _ in range(rnd.randint(0, 50)))
    seqcase("text", a, b, rnd.random() < 0.5, finds=2)

# 3. text with a junk predicate (blanks and tabs), Python's documented use
for _ in range(100):
    al = rnd.choice(["ab ", "a b\t", "abc  "])
    a = "".join(rnd.choice(al) for _ in range(rnd.randint(0, 40)))
    b = "".join(edit(list(a), list(al), rnd.randint(0, 5)))
    seqcase("text", a, b, rnd.random() < 0.5, isjunk=lambda c: c in " \t", jname="blank", finds=2)

# 4. u64 sequences
for _ in range(170):
    k = rnd.randint(1, 9)
    big = rnd.random() < 0.2
    pool = [rnd.getrandbits(64) if big else i for i in range(k)]
    a = [rnd.choice(pool) for _ in range(rnd.randint(0, 40))]
    b = edit(a, pool, rnd.randint(0, 8)) if rnd.random() < 0.6 else [rnd.choice(pool) for _ in range(rnd.randint(0, 40))]
    seqcase("u64", a, b, rnd.random() < 0.5, groups=(3,), finds=1)
for _ in range(100):
    pool = list(range(rnd.randint(2, 9)))
    a = [rnd.choice(pool) for _ in range(rnd.randint(0, 40))]
    b = edit(a, pool, rnd.randint(0, 8))
    seqcase("u64", a, b, rnd.random() < 0.5, isjunk=lambda x: x % 3 == 0, jname="mod3", finds=2)

# 5. structured edits of token lists
for _ in range(250):
    pool = rnd.sample(WORDS, rnd.randint(4, 14))
    a = [rnd.choice(pool) for _ in range(rnd.randint(5, 90))]
    b = edit(a, pool, rnd.randint(0, 10))
    seqcase("str", a, b, rnd.random() < 0.5, groups=(rnd.choice([1, 3]),), finds=1)

# 6. autojunk: len(b) around 200, popular elements
for blen in [150, 190, 198, 199, 200, 201, 202, 250, 299, 300, 301, 330] * 3:
    pool = ["w%d" % i for i in range(rnd.randint(3, 60))]
    wt = [1.0 / (i + 1) for i in range(len(pool))]
    b = rnd.choices(pool, wt, k=blen)
    a = edit(b, pool, rnd.randint(0, 30)) if rnd.random() < 0.7 else rnd.choices(pool, wt, k=rnd.randint(150, 330))
    seqcase("str", a, b, True, groups=(3,), finds=2)
    if rnd.random() < 0.6:
        seqcase("str", a, b, False)

# 7. real listing lines: dx9 vs dx11 and base vs head of the same function listing, windows of lines
asm = sorted(glob.glob(os.path.join(REPO, "build", "decl_budget", "*", "*", "cl_trace", "*.asm")))
texts = [open(p, encoding="utf-8", errors="replace").read().splitlines() for p in asm]


def norm(l):
    return " ".join(l.split())


for t1 in range(len(texts)):
    for t2 in range(len(texts)):
        if t1 == t2:
            continue
        A, B = texts[t1], texts[t2]
        for _ in range(1):
            st = rnd.randrange(0, max(1, min(len(A), len(B)) - 260))
            ln = rnd.randint(60, 160)
            a = [norm(x) for x in A[st : st + ln]]
            b = [norm(x) for x in B[st + rnd.randint(-5, 5) : st + ln + rnd.randint(-5, 5)]] if rnd.random() < 0.7 else [norm(x) for x in edit(A[st : st + ln], A[st : st + ln] or [""], 6)]
            seqcase("str", a, b, rnd.random() < 0.5, groups=(3,))

# 8. unified_diff
def mk(nmin, nmax, pool):
    return [rnd.choice(pool) + "\n" for _ in range(rnd.randint(nmin, nmax))]


for _ in range(170):
    pool = ["line %d" % i for i in range(rnd.randint(2, 30))] + ["", "}", "{", "\ttab", "é"]
    a = mk(0, 40, pool)
    b = edit(a, [x + "\n" for x in pool], rnd.randint(0, 6))
    udiff_case(a, b, rnd.choice(["", "a/x.c", "before"]), rnd.choice(["", "b/x.c", "after"]),
               rnd.choice(["", "", "2005-01-26 23:30:50"]), rnd.choice(["", "", "2010-04-02 10:20:52"]),
               rnd.choice([0, 1, 2, 3, 3, 5]), "\n")
for _ in range(80):  # no line ends: lineterm "" (draft_loop, proto_apply)
    pool = ["line %d" % i for i in range(rnd.randint(2, 30))] + ["", "x"]
    a = [rnd.choice(pool) for _ in range(rnd.randint(0, 40))]
    b = edit(a, pool, rnd.randint(0, 6))
    udiff_case(a, b, "before", "best", "", "", rnd.choice([0, 1, 3]), "")
udiff_case([], [], "a", "b", "", "", 0, "\n")
udiff_case([], [], "a", "b", "", "", 3, "\n")
udiff_case(["x\n"], ["x\n"], "a", "b", "", "", 0, "\n")
udiff_case(["x\n"], [], "a", "b", "", "", 3, "\n")
udiff_case([], ["x\n", "y\n"], "a", "b", "d1", "d2", 3, "\r\n")
for _ in range(6):  # long inputs: unified_diff uses autojunk on, so popular lines are pruned
    pool = ["l%d\n" % i for i in range(40)]
    a = [rnd.choice(pool) for _ in range(rnd.randint(200, 260))]
    b = edit(a, pool, rnd.randint(1, 12))
    udiff_case(a, b, "a/big", "b/big", "", "", rnd.choice([1, 3]), "\n")
# real source files: an old and the current version
try:
    for path in ["tools/gate.py", "tools/lane_lock.py"]:
        cur = open(os.path.join(REPO, path), encoding="utf-8").read().splitlines(True)
        old = subprocess.run(["git", "-C", REPO, "show", "HEAD~40:" + path], capture_output=True, text=True, encoding="utf-8").stdout.splitlines(True)
        if old:
            st = rnd.randrange(0, max(1, len(cur) - 400))
            udiff_case(old[st : st + 100], cur[st : st + 100], "a/" + path, "b/" + path, "", "", 3, "\n")
            seqcase("str", [x.rstrip("\r\n") for x in old[st : st + 210]], [x.rstrip("\r\n") for x in cur[st : st + 210]], False, groups=(3,))
            seqcase("str", [x.rstrip("\r\n") for x in old[st : st + 210]], [x.rstrip("\r\n") for x in cur[st : st + 210]], True)
except Exception as e:
    print("real source skipped:", e, file=sys.stderr)

with open(OUT, "w", encoding="utf-8", newline="\n") as f:
    src = open(sys.argv[0], encoding="utf-8").read().replace("* /", "* /")
    f.write("/* Generated from CPython 3.14.8's difflib by the script at the end of this comment: SequenceMatcher (ratio,\n")
    f.write(" * quick_ratio, real_quick_ratio, get_opcodes, get_grouped_opcodes, find_longest_match) and unified_diff on\n")
    f.write(" * random, structured and real inputs. Records, one per entry:\n")
    f.write(" *   C <mode> <autojunk> <junk>  start of a sequence case (mode str | u64 | text; junk - | blank | mod3)\n")
    f.write(" *   a:<s> b:<s>  the elements  (text mode: the two strings), n <na> <nb> their counts\n")
    f.write(" *   R <ratio> <quick> <real>  the doubles as 16 hex digits of their bits\n")
    f.write(" *   O <k> then k lines o <tag> i1 i2 j1 j2   get_opcodes()    G <n> <groups>, g <k>, o ...  grouped opcodes\n")
    f.write(" *   L alo ahi blo bhi i j k   find_longest_match    E  end of case\n")
    f.write(" *   U <na> <nb> <nout>, f: t: F: T: l: (names, dates, lineterm), N <n>, a: b:, x: expected lines   unified_diff\n")
    f.write(" * Strings use octal escapes. Regenerate: python gen.py <repo root> difflib_corpus.h\n")
    f.write(" * The listing windows come from the VC8 listings under build/decl_budget (cl_trace/*.asm) of that run.\n *\n")
    f.write(src)
    f.write("* /\n")
    f.write("static const char *const difflib_corpus[] = {\n")
    import re
    for s in lines_out:
        s = re.sub(r'(\\[0-7]{3})(?=[0-9])', r'\1""', s)
        f.write('"' + s + '",\n')
    f.write("};\n")
    f.write("#define DIFFLIB_CORPUS_LEN (sizeof difflib_corpus / sizeof difflib_corpus[0])\n")
print(len(lines_out), "entries", os.path.getsize(OUT), "bytes")
*/
